                # The original definition found. Override it!
                pass
            elif other.aliased is False and aliased:
                # The original definition is already registered.
                return
            else:
                # duplicated
                logger.warning(
                    __(
                        'duplicate object description of %s, '
                        'other instance in %s, use :no-index: for one of them'
                    ),
                    name,
                    other.docname,
                    location=location,
                )
        self.objects[name] = ObjectEntry(
            self.env.current_document.docname, node_id, objtype, aliased
        )

    @property
    def modules(self) -> dict[str, ModuleEntry]:
        return self.data.setdefault('modules', {})  # modname -> ModuleEntry

    def note_module(
        self, name: str, node_id: str, synopsis: str, platform: str, deprecated: bool
    ) -> None:
        """Note a python module for cross reference.

        .. versionadded:: 2.1
        """
        self.modules[name] = ModuleEntry(
            docname=self.env.current_document.docname,
            node_id=node_id,
            synopsis=synopsis,
            platform=platform,
            deprecated=deprecated,
        )

    def clear_doc(self, docname: str) -> None:
        to_remove = [
            fullname for fullname, obj in self.objects.items() if obj.docname == docname
        ]
        for fullname in to_remove:
            del self.objects[fullname]
        to_remove = [
            modname for modname, mod in self.modules.items() if mod.docname == docname
        ]
        for fullname in to_remove:
            del self.modules[fullname]

    def merge_domaindata(self, docnames: Set[str], otherdata: dict[str, Any]) -> None:
        # XXX check duplicates?
        for fullname, obj in otherdata['objects'].items():
            if obj.docname in docnames:
                self.objects[fullname] = obj
        for modname, mod in otherdata['modules'].items():
            if mod.docname in docnames:
                self.modules[modname] = mod

    def find_obj(
        self,
        env: BuildEnvironment,
        modname: str,
        classname: str,
        name: str,
        type: str | None,
        searchmode: int = 0,
    ) -> list[tuple[str, ObjectEntry]]:
        """Find a Python object for "name", perhaps using the given module
        and/or classname.  Returns a list of (name, object entry) tuples.
        """
        # skip parens
        name = name.removesuffix('()')

        if not name:
            return []

        matches: list[tuple[str, ObjectEntry]] = []

        newname = None
        if searchmode == 1:
            if type is None:
                objtypes: list[str] | None = list(self.object_types)
            else:
                objtypes = self.objtypes_for_role(type)
            if objtypes is not None:
                if modname and classname:
                    fullname = modname + '.' + classname + '.' + name
                    if (
                        fullname in self.objects
                        and self.objects[fullname].objtype in objtypes
                    ):
                        newname = fullname
                if not newname:
                    if (
                        modname
                        and f'{modname}.{name}' in self.objects
                        and self.objects[f'{modname}.{name}'].objtype in objtypes
                    ):
                        newname = f'{modname}.{name}'
                    elif (
                        name in self.objects and self.objects[name].objtype in objtypes
                    ):
                        newname = name
                    else:
                        # "fuzzy" searching mode
                        searchname = f'.{name}'
                        matches = [
                            (oname, self.objects[oname])
                            for oname in self.objects
                            if oname.endswith(searchname)
                            and self.objects[oname].objtype in objtypes
                        ]
        else:
            # NOTE: searching for exact match, object type is not considered
            if name in self.objects:
                newname = name
            elif type == 'mod':
                # only exact matches allowed for modules
                return []
            elif classname and classname + '.' + name in self.objects:
                newname = classname + '.' + name
            elif modname and modname + '.' + name in self.objects:
                newname = modname + '.' + name
            elif (
                modname
                and classname
                and modname + '.' + classname + '.' + name in self.objects
            ):
                newname = modname + '.' + classname + '.' + name
        if newname is not None:
            matches.append((newname, self.objects[newname]))
        return matches

    def resolve_xref(
        self,
        env: BuildEnvironment,
        fromdocname: str,
        builder: Builder,
        type: str,
        target: str,
        node: pending_xref,
        contnode: Element,
    ) -> nodes.reference | None:
        modname = node.get('py:module')
        clsname = node.get('py:class')
        searchmode = 1 if node.hasattr('refspecific') else 0
        matches = self.find_obj(env, modname, clsname, target, type, searchmode)

        if not matches and type == 'class':
            # fallback to data/attr (for type aliases)
            # type aliases are documented as data/attr but referenced as class
            matches = self.find_obj(env, modname, clsname, target, 'data', searchmode)
            if not matches:
                matches = self.find_obj(
                    env, modname, clsname, target, 'attr', searchmode
                )
        if not matches and type == 'attr':
            # fallback to meth (for property; Sphinx 2.4.x)
            # this ensures that `:attr:` role continues to refer to the old property entry
            # that defined by ``method`` directive in old reST files.
            matches = self.find_obj(env, modname, clsname, target, 'meth', searchmode)
        if not matches and type == 'meth':
            # fallback to attr (for property)
            # this ensures that `:meth:` in the old reST files can refer to the property
            # entry that defined by ``property`` directive.
            #
            # Note: _prop is a secret role only for internal look-up.
            matches = self.find_obj(env, modname, clsname, target, '_prop', searchmode)

        if not matches:
            return None
        elif len(matches) > 1:
            canonicals = [m for m in matches if not m[1].aliased]
            if len(canonicals) == 1:
                matches = canonicals
            else:
                logger.warning(
                    __('more than one target found for cross-reference %r: %s'),
                    target,
                    ', '.join(match[0] for match in matches),
                    type='ref',
                    subtype='python',
                    location=node,
                )
        name, obj = matches[0]

        if obj[2] == 'module':
            return self._make_module_refnode(builder, fromdocname, name, contnode)
        else:
            # determine the content of the reference by conditions
            content = find_pending_xref_condition(node, 'resolved')
            if content:
                children = content.children
            else:
                # if not found, use contnode
                children = [contnode]

            return make_refnode(builder, fromdocname, obj[0], obj[1], children, name)

    def resolve_any_xref(
        self,
        env: BuildEnvironment,
        fromdocname: str,
        builder: Builder,
        target: str,
        node: pending_xref,
        contnode: Element,
    ) -> list[tuple[str, nodes.reference]]:
        modname = node.get('py:module')
        clsname = node.get('py:class')
        results: list[tuple[str, nodes.reference]] = []

        # always search in "refspecific" mode with the :any: role
        matches = self.find_obj(env, modname, clsname, target, None, 1)
        multiple_matches = len(matches) > 1

        for name, obj in matches:
            if multiple_matches and obj.aliased:
                # Skip duplicated matches
                continue

            if obj[2] == 'module':
                results.append((
                    'py:mod',
                    self._make_module_refnode(builder, fromdocname, name, contnode),
                ))
            else:
                # determine the content of the reference by conditions
                content = find_pending_xref_condition(node, 'resolved')
                if content:
                    children = content.children
                else:
                    # if not found, use contnode
                    children = [contnode]

                role = 'py:' + self.role_for_objtype(obj[2])  # type: ignore[operator]
                results.append((
                    role,
                    make_refnode(builder, fromdocname, obj[0], obj[1], children, name),
                ))
        return results

    def _make_module_refnode(
        self, builder: Builder, fromdocname: str, name: str, contnode: Node
    ) -> nodes.reference:
        # get additional info for modules
        module: ModuleEntry = self.modules[name]
        title_parts = [name]
        if module.synopsis:
            title_parts.append(f': {module.synopsis}')
        if module.deprecated:
            title_parts.append(_(' (deprecated)'))
        if module.platform:
            title_parts.append(f' ({module.platform})')
        title = ''.join(title_parts)
        return make_refnode(
            builder, fromdocname, module.docname, module.node_id, contnode, title
        )

    def get_objects(self) -> Iterator[tuple[str, str, str, str, str, int]]:
        for modname, mod in self.modules.items():
            yield modname, modname, 'module', mod.docname, mod.node_id, 0
        for refname, obj in self.objects.items():
            if obj.objtype != 'module':  # modules are already handled
                if obj.aliased:
                    # aliased names are not full-text searchable.
                    yield refname, refname, obj.objtype, obj.docname, obj.node_id, -1
                else:
                    yield refname, refname, obj.objtype, obj.docname, obj.node_id, 1

    def get_full_qualified_name(self, node: Element) -> str | None:
        modname = node.get('py:module')
        clsname = node.get('py:class')
        target = node.get('reftarget')
        if target is None:
            return None
        else:
            return '.'.join(filter(None, [modname, clsname, target]))


def builtin_resolver(
    app: Sphinx, env: BuildEnvironment, node: pending_xref, contnode: Element
) -> Element | None:
    """Do not emit nitpicky warnings for built-in types."""
    if node.get('refdomain') != 'py':
        return None
    elif node.get('reftype') in {'class', 'obj'} and node.get('reftarget') == 'None':
        return contnode
    elif node.get('reftype') in {'class', 'obj', 'exc'}:
        reftarget = node.get('reftarget')
        if inspect.isclass(getattr(builtins, reftarget, None)):
            # built-in class
            return contnode
        if _is_typing(reftarget):
            # typing class
            return contnode

    return None


def _is_typing(s: str, /) -> bool:
    return s.removeprefix('typing.') in _TYPING_ALL


def setup(app: Sphinx) -> ExtensionMetadata:
    app.setup_extension('sphinx.directives')

    app.add_domain(PythonDomain)
    app.add_config_value(
        'python_use_unqualified_type_names', False, 'env', types=frozenset({bool})
    )
    app.add_config_value(
        'python_maximum_signature_line_length',
        None,
        'env',
        types=frozenset({int, NoneType}),
    )
    app.add_config_value(
        'python_trailing_comma_in_multi_line_signatures',
        True,
        'env',
        types=frozenset({bool}),
    )
    app.add_config_value(
        'python_display_short_literal_types', False, 'env', types=frozenset({bool})
    )
    app.connect('object-description-transform', filter_meta_fields)
    app.connect('missing-reference', builtin_resolver, priority=900)

    return {
        'version': 'builtin',
        'env_version': 4,
        'parallel_read_safe': True,
        'parallel_write_safe': True,
    }

    nodes.container: ('code-block', None),
}

def __init__(self, env: BuildEnvironment) -> None:
    super().__init__(env)

    # set up enumerable nodes

    # create a copy for this instance
    self.enumerable_nodes = copy(self.enumerable_nodes)  # type: ignore[misc]
    for node, settings in env._registry.enumerable_nodes.items():
        self.enumerable_nodes[node] = settings

def note_hyperlink_target(
    self, name: str, docname: str, node_id: str, title: str = ''
) -> None:
    """Add a hyperlink target for cross reference.

    .. warning::

       This is only for internal use.  Please don't use this from your extension.
       ``document.note_explicit_target()`` or ``note_implicit_target()`` are recommended to
       add a hyperlink target to the document.

       This only adds a hyperlink target to the StandardDomain.  And this does not add a
       node_id to node.  Therefore, it is very fragile to calling this without
       understanding hyperlink target framework in both docutils and Sphinx.

    .. versionadded:: 3.0
    """
    if name in self.anonlabels and self.anonlabels[name] != (docname, node_id):
        logger.warning(
            __('duplicate label %s, other instance in %s'),
            name,
            self.env.doc2path(self.anonlabels[name][0]),
        )

    self.anonlabels[name] = (docname, node_id)
    if title:
        self.labels[name] = (docname, node_id, title)

@property
def objects(self) -> dict[tuple[str, str], tuple[str, str]]:
    # (objtype, name) -> docname, labelid
    return self.data.setdefault('objects', {})

def note_object(
    self, objtype: str, name: str, labelid: str, location: Any = None
) -> None:
    """Note a generic object for cross reference.

    .. versionadded:: 3.0
    """
    if (objtype, name) in self.objects:
        docname = self.objects[objtype, name][0]
        logger.warning(
            __('duplicate %s description of %s, other instance in %s'),
            objtype,
            name,
            docname,
            location=location,
        )
    self.objects[objtype, name] = (self.env.current_document.docname, labelid)

@property
def _terms(self) -> dict[str, tuple[str, str]]:
    """.. note:: Will be removed soon. internal use only."""
    return self.data.setdefault('terms', {})  # (name) -> docname, labelid

def _note_term(self, term: str, labelid: str, location: Any = None) -> None:
    """Note a term for cross reference.

    .. note:: Will be removed soon. internal use only.
    """
    self.note_object('term', term, labelid, location)

    self._terms[term.lower()] = (self.env.current_document.docname, labelid)

@property
def progoptions(self) -> dict[tuple[str | None, str], tuple[str, str]]:
    return self.data.setdefault(
        'progoptions', {}
    )  # (program, name) -> docname, labelid

@property
def labels(self) -> dict[str, tuple[str, str, str]]:
    return self.data.setdefault(
        'labels', {}
    )  # labelname -> docname, labelid, sectionname

@property
def anonlabels(self) -> dict[str, tuple[str, str]]:
    return self.data.setdefault('anonlabels', {})  # labelname -> docname, labelid

def clear_doc(self, docname: str) -> None:
    to_remove1 = [
        key for key, (fn, _l) in self.progoptions.items() if fn == docname
    ]
    for key1 in to_remove1:
        del self.progoptions[key1]

    to_remove2 = [key for key, (fn, _l) in self.objects.items() if fn == docname]
    for key2 in to_remove2:
        del self.objects[key2]

    to_remove3 = [key for key, (fn, _l) in self._terms.items() if fn == docname]
    for key3 in to_remove3:
        del self._terms[key3]

    to_remove3 = [key for key, (fn, _l, _l) in self.labels.items() if fn == docname]
    for key3 in to_remove3:
        del self.labels[key3]

    to_remove3 = [key for key, (fn, _l) in self.anonlabels.items() if fn == docname]
    for key3 in to_remove3:
        del self.anonlabels[key3]

def merge_domaindata(self, docnames: Set[str], otherdata: dict[str, Any]) -> None:
    # XXX duplicates?
    for key, data in otherdata['progoptions'].items():
        if data[0] in docnames:
            self.progoptions[key] = data
    for key, data in otherdata['objects'].items():
        if data[0] in docnames:
            self.objects[key] = data
    for key, data in otherdata['terms'].items():
        if data[0] in docnames:
            self._terms[key] = data
    for key, data in otherdata['labels'].items():
        if data[0] in docnames:
            self.labels[key] = data
    for key, data in otherdata['anonlabels'].items():
        if data[0] in docnames:
            self.anonlabels[key] = data

def process_doc(
    self, env: BuildEnvironment, docname: str, document: nodes.document
) -> None:
    for name, explicit in document.nametypes.items():
        if not explicit:
            continue
        labelid = document.nameids[name]
        if labelid is None:
            continue
        node = document.ids[labelid]
        if isinstance(node, nodes.target) and 'refid' in node:
            # indirect hyperlink targets
            node = document.ids.get(node['refid'])  # type: ignore[assignment]
            labelid = node['names'][0]
        if (
            node.tagname == 'footnote'
            or 'refuri' in node
            or node.tagname.startswith('desc_')
        ):
            # ignore footnote labels, labels automatically generated from a
            # link and object descriptions
            continue
        if name in self.labels:
            logger.warning(
                __('duplicate label %s, other instance in %s'),
                name,
                env.doc2path(self.labels[name][0]),
                location=node,
            )
        self.anonlabels[name] = docname, labelid
        if node.tagname == 'section':
            title = cast('nodes.title', node[0])
            sectname = clean_astext(title)
        elif node.tagname == 'rubric':
            sectname = clean_astext(node)
        elif self.is_enumerable_node(node):
            sectname = self.get_numfig_title(node) or ''
            if not sectname:
                continue
        else:
            if (
                isinstance(node, (nodes.definition_list, nodes.field_list))
                and node.children
            ):
                node = cast('nodes.Element', node.children[0])
            if isinstance(node, (nodes.field, nodes.definition_list_item)):
                node = cast('nodes.Element', node.children[0])
            if isinstance(node, (nodes.term, nodes.field_name)):
                sectname = clean_astext(node)
            else:
                toctree = next(node.findall(addnodes.toctree), None)
                if toctree and toctree.get('caption'):
                    sectname = toctree['caption']
                else:
                    # anonymous-only labels
                    continue
        self.labels[name] = docname, labelid, sectname

def add_program_option(
    self, program: str | None, name: str, docname: str, labelid: str
) -> None:
    # prefer first command option entry
    if (program, name) not in self.progoptions:
        self.progoptions[program, name] = (docname, labelid)

def build_reference_node(
    self,
    fromdocname: str,
    builder: Builder,
    docname: str,
    labelid: str,
    sectname: str,
    rolename: str,
    *,
    node_class: type[nodes.reference] = nodes.reference,
    **options: Any,
) -> nodes.reference:
    newnode = node_class('', '', internal=True, **options)
    innernode = nodes.inline(sectname, sectname)
    if innernode.get('classes') is not None:
        innernode['classes'].append('std')
        innernode['classes'].append('std-' + rolename)
    if docname == fromdocname:
        newnode['refid'] = labelid
    else:
        # set more info in contnode; in case the
        # get_relative_uri call raises NoUri,
        # the builder will then have to resolve these
        contnode = pending_xref('')
        contnode['refdocname'] = docname
        contnode['refsectname'] = sectname
        newnode['refuri'] = builder.get_relative_uri(fromdocname, docname)
        if labelid:
            newnode['refuri'] += '#' + labelid
    newnode.append(innernode)
    return newnode

def resolve_xref(
    self,
    env: BuildEnvironment,
    fromdocname: str,
    builder: Builder,
    typ: str,
    target: str,
    node: pending_xref,
    contnode: Element,
) -> nodes.reference | None:
    if typ == 'ref':
        resolver = self._resolve_ref_xref
    elif typ == 'numref':
        resolver = self._resolve_numref_xref  # type: ignore[assignment]
    elif typ == 'keyword':
        resolver = self._resolve_keyword_xref
    elif typ == 'doc':
        resolver = self._resolve_doc_xref
    elif typ == 'option':
        resolver = self._resolve_option_xref
    elif typ == 'term':
        resolver = self._resolve_term_xref
    else:
        resolver = self._resolve_obj_xref

    return resolver(env, fromdocname, builder, typ, target, node, contnode)

def _resolve_ref_xref(
    self,
    env: BuildEnvironment,
    fromdocname: str,
    builder: Builder,
    typ: str,
    target: str,
    node: pending_xref,
    contnode: Element,
) -> nodes.reference | None:
    if node['refexplicit']:
        # reference to anonymous label; the reference uses
        # the supplied link caption
        docname, labelid = self.anonlabels.get(target, ('', ''))
        sectname = node.astext()
    else:
        # reference to named label; the final node will
        # contain the section name after the label
        docname, labelid, sectname = self.labels.get(target, ('', '', ''))
    if not docname:
        return None

    return self.build_reference_node(
        fromdocname, builder, docname, labelid, sectname, 'ref'
    )

def _resolve_numref_xref(
    self,
    env: BuildEnvironment,
    fromdocname: str,
    builder: Builder,
    typ: str,
    target: str,
    node: pending_xref,
    contnode: Element,
) -> nodes.reference | Element | None:
    if target in self.labels:
        docname, labelid, figname = self.labels.get(target, ('', '', ''))
    else:
        docname, labelid = self.anonlabels.get(target, ('', ''))
        figname = None

    if not docname:
        return None

    target_node = env.get_doctree(docname).ids.get(labelid)
    assert target_node is not None
    figtype = self.get_enumerable_node_type(target_node)
    if figtype is None:
        return None

    if figtype != 'section' and env.config.numfig is False:
        logger.warning(
            __('numfig is disabled. :numref: is ignored.'), location=node
        )
        return contnode

    try:
        fignumber = self.get_fignumber(env, builder, figtype, docname, target_node)
        if fignumber is None:
            return contnode
    except ValueError:
        logger.warning(
            __(
                'Failed to create a cross reference. Any number is not assigned: %s'
            ),
            labelid,
            location=node,
        )
        return contnode

    try:
        if node['refexplicit']:
            title = contnode.astext()
        else:
            title = env.config.numfig_format.get(figtype, '')

        if figname is None and '{name}' in title:
            logger.warning(__('the link has no caption: %s'), title, location=node)
            return contnode
        else:
            fignum = '.'.join(map(str, fignumber))
            if '{name}' in title or 'number' in title:
                # new style format (cf. "Fig.{number}")
                if figname:
                    newtitle = title.format(name=figname, number=fignum)
                else:
                    newtitle = title.format(number=fignum)
            else:
                # old style format (cf. "Fig.%s")
                newtitle = title % fignum
    except KeyError as exc:
        logger.warning(
            __('invalid numfig_format: %s (%r)'), title, exc, location=node
        )
        return contnode
    except TypeError:
        logger.warning(__('invalid numfig_format: %s'), title, location=node)
        return contnode

    return self.build_reference_node(
        fromdocname,
        builder,
        docname,
        labelid,
        newtitle,
        'numref',
        node_class=addnodes.number_reference,
        title=title,
    )

def _resolve_keyword_xref(
    self,
    env: BuildEnvironment,
    fromdocname: str,
    builder: Builder,
    typ: str,
    target: str,
    node: pending_xref,
    contnode: Element,
) -> nodes.reference | None:
    # keywords are oddballs: they are referenced by named labels
    docname, labelid, _ = self.labels.get(target, ('', '', ''))
    if not docname:
        return None
    return make_refnode(builder, fromdocname, docname, labelid, contnode)

def _resolve_doc_xref(
    self,
    env: BuildEnvironment,
    fromdocname: str,
    builder: Builder,
    typ: str,
    target: str,
    node: pending_xref,
    contnode: Element,
) -> nodes.reference | None:
    # directly reference to document by source name; can be absolute or relative
    refdoc = node.get('refdoc', fromdocname)
    docname = docname_join(refdoc, node['reftarget'])
    if docname not in env.all_docs:

            return None
        else:
            if node['refexplicit']:
                # reference with explicit title
                caption = node.astext()
            else:
                caption = clean_astext(env.titles[docname])
            innernode = nodes.inline(caption, caption, classes=['doc'])
            return make_refnode(builder, fromdocname, docname, None, innernode)

    def _resolve_option_xref(
        self,
        env: BuildEnvironment,
        fromdocname: str,
        builder: Builder,
        typ: str,
        target: str,
        node: pending_xref,
        contnode: Element,
    ) -> nodes.reference | None:
        progname = node.get('std:program')
        target = target.strip()
        docname, labelid = self.progoptions.get((progname, target), ('', ''))
        if not docname:
            # Support also reference that contain an option value:
            # * :option:`-foo=bar`
            # * :option:`-foo[=bar]`
            # * :option:`-foo bar`
            for needle in ('=', '[=', ' '):
                if needle in target:
                    stem, _, _ = target.partition(needle)
                    docname, labelid = self.progoptions.get((progname, stem), ('', ''))
                    if docname:
                        break
        if not docname:
            commands = []
            while ws_re.search(target):
                subcommand, target = ws_re.split(target, maxsplit=1)
                commands.append(subcommand)
                progname = '-'.join(commands)

                docname, labelid = self.progoptions.get((progname, target), ('', ''))
                if docname:
                    break
            else:
                return None

        return make_refnode(builder, fromdocname, docname, labelid, contnode)

    def _resolve_term_xref(
        self,
        env: BuildEnvironment,
        fromdocname: str,
        builder: Builder,
        typ: str,
        target: str,
        node: pending_xref,
        contnode: Element,
    ) -> nodes.reference | None:
        result = self._resolve_obj_xref(
            env, fromdocname, builder, typ, target, node, contnode
        )
        if result:
            return result
        else:
            # fallback to case insensitive match
            if target.lower() in self._terms:
                docname, labelid = self._terms[target.lower()]
                return make_refnode(builder, fromdocname, docname, labelid, contnode)
            else:
                return None

    def _resolve_obj_xref(
        self,
        env: BuildEnvironment,
        fromdocname: str,
        builder: Builder,
        typ: str,
        target: str,
        node: pending_xref,
        contnode: Element,
    ) -> nodes.reference | None:
        objtypes = self.objtypes_for_role(typ) or []
        for objtype in objtypes:
            if (objtype, target) in self.objects:
                docname, labelid = self.objects[objtype, target]
                break
        else:
            docname, labelid = '', ''
        if not docname:
            return None
        return make_refnode(builder, fromdocname, docname, labelid, contnode)

    def resolve_any_xref(
        self,
        env: BuildEnvironment,
        fromdocname: str,
        builder: Builder,
        target: str,
        node: pending_xref,
        contnode: Element,
    ) -> list[tuple[str, nodes.reference]]:
        results: list[tuple[str, nodes.reference]] = []
        ltarget = target.lower()  # :ref: lowercases its target automatically
        for role in ('ref', 'option'):  # do not try "keyword"
            res = self.resolve_xref(
                env,
                fromdocname,
                builder,
                role,
                ltarget if role == 'ref' else target,
                node,
                contnode,
            )
            if res:
                results.append(('std:' + role, res))
        # all others
        for objtype in self.object_types:
            key = (objtype, target)
            if objtype == 'term':
                key = (objtype, ltarget)
            if key in self.objects:
                docname, labelid = self.objects[key]
                role = 'std:' + self.role_for_objtype(objtype)  # type: ignore[operator]
                results.append((
                    role,
                    make_refnode(builder, fromdocname, docname, labelid, contnode),
                ))
        return results

    def get_objects(self) -> Iterator[tuple[str, str, str, str, str, int]]:
        # handle the special 'doc' reference here
        for doc in self.env.all_docs:
            yield doc, clean_astext(self.env.titles[doc]), 'doc', doc, '', -1
        for (prog, option), info in self.progoptions.items():
            if prog:
                fullname = f'{prog}.{option}'
                yield fullname, fullname, 'cmdoption', info[0], info[1], 1
            else:
                yield option, option, 'cmdoption', info[0], info[1], 1
        for (type, name), info in self.objects.items():
            yield (
                name,
                name,
                type,
                info[0],
                info[1],
                self.object_types[type].attrs['searchprio'],
            )
        for name, (docname, labelid, sectionname) in self.labels.items():
            yield name, sectionname, 'label', docname, labelid, -1
        # add anonymous-only labels as well
        non_anon_labels = set(self.labels)
        for name, (docname, labelid) in self.anonlabels.items():
            if name not in non_anon_labels:
                yield name, name, 'label', docname, labelid, -1

    def get_type_name(self, type: ObjType, primary: bool = False) -> str:
        # never prepend "Default"
        return type.lname

    def is_enumerable_node(self, node: Node) -> bool:
        return node.__class__ in self.enumerable_nodes

    def get_numfig_title(self, node: Node) -> str | None:
        """Get the title of enumerable nodes to refer them using its title"""
        if self.is_enumerable_node(node):
            elem = cast('Element', node)
            _, title_getter = self.enumerable_nodes.get(elem.__class__, (None, None))
            if title_getter:
                return title_getter(elem)
            else:
                for subnode in elem:
                    if isinstance(subnode, (nodes.caption, nodes.title)):
                        return clean_astext(subnode)

        return None

    def get_enumerable_node_type(self, node: Node) -> str | None:
        """Get type of enumerable nodes."""
        if isinstance(node, nodes.section):
            return 'section'
        elif (
            isinstance(node, nodes.container)
            and 'literal_block' in node
            and _has_child(node, nodes.literal_block)
        ):
            # given node is a code-block having caption
            return 'code-block'
        else:
            figtype, _ = self.enumerable_nodes.get(node.__class__, (None, None))
            return figtype

    def get_fignumber(
        self,
        env: BuildEnvironment,
        builder: Builder,
        figtype: str,
        docname: str,
        target_node: Element,
    ) -> tuple[int, ...] | None:
        if figtype == 'section':
            if builder.name == 'latex':
                return ()
            elif docname not in env.toc_secnumbers:
                raise ValueError  # no number assigned
            else:
                anchorname = '#' + target_node['ids'][0]
                if anchorname not in env.toc_secnumbers[docname]:
                    # try first heading which has no anchor
                    return env.toc_secnumbers[docname].get('')
                else:
                    return env.toc_secnumbers[docname].get(anchorname)
        else:
            try:
                figure_id = target_node['ids'][0]
                return env.toc_fignumbers[docname][figtype][figure_id]
            except (KeyError, IndexError) as exc:
                # target_node is found, but fignumber is not assigned.
                # Maybe it is defined in orphaned document.
                raise ValueError from exc

    def get_full_qualified_name(self, node: Element) -> str | None:
        if node.get('reftype') == 'option':
            progname = node.get('std:program')
            command = ws_re.split(node.get('reftarget'))
            if progname:
                command.insert(0, progname)
            option = command.pop()
            if command:
                command_str = '-'.join(command)
                return f'{command_str}.{option}'
            else:
                return None
        else:
            return None


def _has_child(node: Element, cls: type) -> bool:
    return any(isinstance(child, cls) for child in node)


def warn_missing_reference(
    app: Sphinx,
    domain: Domain,
    node: pending_xref,
) -> bool | None:
    if (domain and domain.name != 'std') or node['reftype'] != 'ref':
        return None
    else:
        target = node['reftarget']
        if target not in domain.anonlabels:  # type: ignore[attr-defined]
            msg = __('undefined label: %r')
        else:
            msg = __(
                'Failed to create a cross reference. A title or caption not found: %r'
            )

        logger.warning(msg, target, location=node, type='ref', subtype=node['reftype'])
        return True


def setup(app: Sphinx) -> ExtensionMetadata:
    app.add_domain(StandardDomain)
    app.connect('warn-missing-reference', warn_missing_reference)

    return {
        'version': 'builtin',
        'env_version': 2,
        'parallel_read_safe': True,
        'parallel_write_safe': True,
